package glitch

import data.glitch_lib

# Weak cryptographic keywords to detect in any string value
weak_crypto_keywords := ["DES", "3DES", "RC2", "RC4", "Blowfish", "CAST", "IDEA", "SEED", "ARIA", "MD5", "SHA1", "SSLv2", "SSLv3", "TLS1.0", "TLS1.1", "TLSv1.0", "TLSv1.1", "ECB", "NULL", "EXPORT", "ANON", "secp160", "secp192", "secp224", "brainpoolP160", "brainpoolP192", "prime192", "sect163", "HMAC-MD5", "HMAC-SHA1", "PBKDF1", "Math.random", "rand", "srand", "md5_crypt", "CBC"]

# Encryption-related attribute/variable names
crypto_name_patterns := ["algorithm", "cipher", "encryption", "crypto", "key", "tls", "ssl", "hash", "mode", "curve", "kex", "mac", "hmac", "signature", "random", "entropy", "seed", "nonce", "iv", "cert", "verify", "trust", "keystore", "truststore", "password", "secret", "encrypt", "decrypt", "suite", "protocol", "md", "sha"]

# Check if string contains weak crypto keyword
contains_weak_crypto(str) {
    some kw
    weak_crypto_keywords[kw]
    regex.match(sprintf("(?i).*\\b%s\\b.*", [kw]), str)
}

# Check if name is crypto-related
is_crypto_related(name) {
    some pat
    crypto_name_patterns[pat]
    regex.match(sprintf("(?i).*%s.*", [pat]), name)
}

# Recursively check any value for weak crypto strings
has_weak_crypto_in_value(val) {
    val.ir_type == "String"
    contains_weak_crypto(val.value)
} else {
    val.ir_type == "VariableReference"
    contains_weak_crypto(val.value)
} else {
    val.ir_type == "FunctionCall"
    some arg
    val.args[arg]
    has_weak_crypto_in_value(val.args[arg])
} else {
    val.ir_type == "MethodCall"
    has_weak_crypto_in_value(val.receiver)
} else {
    val.ir_type == "Access"
    has_weak_crypto_in_value(val.left)
} else {
    val.ir_type == "Sum"
    has_weak_crypto_in_value(val.left)
} else {
    val.ir_type == "Sum"
    has_weak_crypto_in_value(val.right)
} else {
    val.ir_type == "Array"
    some elem
    val.value[elem]
    has_weak_crypto_in_value(val.value[elem])
} else {
    val.ir_type == "Hash"
    some kv
    val.value[kv]
    has_weak_crypto_in_value(val.value[kv].key)
} else {
    val.ir_type == "Hash"
    some kv
    val.value[kv]
    has_weak_crypto_in_value(val.value[kv].value)
}

# Check numeric value for weak key sizes
is_weak_key_size(val) {
    val.ir_type == "Integer"
    val.value < 2048
} else {
    val.ir_type == "String"
    to_number(val.value) < 2048
}

# Main rule: Detect weak crypto in attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check AtomicUnit attributes
    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]
    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    # Case 1: Crypto-related name with weak value
    is_crypto_related(attr.name)
    has_weak_crypto_in_value(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak or deprecated cryptographic algorithm detected. (CWE-326)"
    }
}

# Detect weak key sizes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]
    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    regex.match("(?i).*(key_size|key_length|key_bits|modulus|rsa_key|dsa_key|dh_param).*", attr.name)
    is_weak_key_size(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Key size below recommended minimum (2048 bits). (CWE-326)"
    }
}

# Detect weak crypto in variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    v := vars[_]

    # Case: Variable name is crypto-related and value contains weak crypto
    is_crypto_related(v.name)
    has_weak_crypto_in_value(v.value)

    result := {
        "type": "sec_weak_crypt",
        "element": v,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak or deprecated cryptographic algorithm in variable. (CWE-326)"
    }
}

# Detect weak crypto in conditional statements (Chef-style)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    conditions := glitch_lib.all_conditional_statements(parent)
    cond := conditions[_]

    some stmt
    cond.statements[stmt]
    stmt.ir_type == "Variable"

    is_crypto_related(stmt.name)
    has_weak_crypto_in_value(stmt.value)

    result := {
        "type": "sec_weak_crypt",
        "element": stmt,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak or deprecated cryptographic algorithm in conditional block. (CWE-326)"
    }
}

# Detect generic weak crypto strings in any attribute value (broader catch-all)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]
    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    # Catch hash functions like md5 in command strings
    has_weak_crypto_in_value(attr.value)
    not is_crypto_related(attr.name)  # Avoid duplicates with previous rules

    # Only flag if the value actually contains a clear weak crypto reference
    some kw
    weak_crypto_keywords[kw]
    regex.match(sprintf("(?i).*\\b%s\\b.*", [kw]), attr.value.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak or deprecated cryptographic primitive detected. (CWE-326)"
    }
}

package glitch

import data.glitch_lib

# Weak cryptographic keywords to detect in specific contexts
weak_crypto_algorithms := {"DES", "3DES", "RC2", "RC4", "Blowfish", "CAST", "IDEA", "SEED", "ARIA", "MD5", "SHA1", "SSLv2", "SSLv3", "TLSv1.0", "TLSv1.1", "TLS1.0", "TLS1.1", "ECB", "NULL", "EXPORT", "ANON", "secp160", "secp192", "secp224", "brainpoolP160", "brainpoolP192", "prime192", "sect163", "HMAC-MD5", "HMAC-SHA1", "PBKDF1"}

# Weak cipher suites or patterns in cipher strings
weak_cipher_patterns := {"_CBC_", "CBC_SHA", "MD5", "SHA1", "SEED", "RC4", "DES", "3DES", "NULL", "EXPORT", "ANON"}

# Password hashing/encryption methods that are weak
weak_password_crypto := {"md5_crypt", "crypt", "des_crypt", "sha1_crypt"}

# Encryption-related attribute/variable names that indicate crypto configuration
crypto_config_names := {"encrypt", "cipher", "cipher_suites", "algorithm", "protocol", "hash", "mode", "tls", "ssl", "crypto", "key_exchange", "named_curve", "mac_algorithm", "signature_algorithm", "random_source", "entropy", "seed", "nonce", "iv"}

# Key size attribute patterns
key_size_names := {"key_size", "key_length", "key_bits", "modulus", "rsa_key_size", "dsa_key_size", "dh_params", "bits", "salt_size", "iterations"}

# Check if value is a direct weak crypto algorithm
is_weak_algorithm(str) {
    weak_crypto_algorithms[kw]
    str == kw
} else {
    weak_crypto_algorithms[kw]
    regex.match(sprintf("(?i)\\b%s\\b", [kw]), str)
}

# Check for weak cipher patterns in cipher suite strings
has_weak_cipher_pattern(str) {
    weak_cipher_patterns[p]
    regex.match(sprintf("(?i).*%s.*", [p]), str)
}

# Check for weak password crypto methods
is_weak_password_crypto(str) {
    weak_password_crypto[m]
    str == m
} else {
    weak_password_crypto[m]
    regex.match(sprintf("(?i)\\b%s\\b", [m]), str)
}

# Check if numeric value indicates weak key size
is_weak_key_size(val) {
    val.ir_type == "Integer"
    val.value < 2048
    val.value > 0
} else {
    val.ir_type == "String"
    safe_to_number(val.value) < 2048
    safe_to_number(val.value) > 0
}

# Safe string to number conversion
safe_to_number(s) = n {
    n := to_number(s)
} else = 0 {
    true
}

# Check if name indicates crypto configuration
is_crypto_config_name(name) {
    crypto_config_names[kw]
    regex.match(sprintf("(?i).*%s.*", [kw]), name)
}

# Check if name indicates key size
is_key_size_name(name) {
    key_size_names[kw]
    regex.match(sprintf("(?i).*%s.*", [kw]), name)
}

# Extract string value from node if it's a String or VariableReference
get_string_value(val) = s {
    val.ir_type == "String"
    s := val.value
} else = s {
    val.ir_type == "VariableReference"
    s := val.value
} else = s {
    val.ir_type == "FunctionCall"
    arg := val.args[_]
    arg.ir_type == "String"
    s := arg.value
}

# Get all values from nested structures (Hash, Array)
walk_values(node, vals) {
    node.ir_type == "String"
    vals := {node.value}
} else = vals {
    node.ir_type == "VariableReference"
    vals := {node.value}
} else = vals {
    node.ir_type == "Integer"
    vals := {sprintf("%d", [node.value])}
} else = vals {
    node.ir_type == "Hash"
    vals := {s |
        pair := node.value[_]
        v := walk_values(pair.value, _)
        s := v[_]
    }
} else = vals {
    node.ir_type == "Array"
    vals := {s |
        elem := node.value[_]
        v := walk_values(elem, _)
        s := v[_]
    }
} else = vals {
    vals := set()
}

# Check hash content for weak crypto
hash_contains_weak_crypto(val) {
    val.ir_type == "Hash"
    pair := val.value[_]
    is_crypto_config_name(pair.key.value)
    s := get_string_value(pair.value)
    is_weak_algorithm(s)
}

hash_contains_weak_crypto(val) {
    val.ir_type == "Hash"
    pair := val.value[_]
    pair.key.value == "encrypt"
    s := get_string_value(pair.value)
    is_weak_password_crypto(s)
}

hash_contains_weak_crypto(val) {
    val.ir_type == "Hash"
    pair := val.value[_]
    is_key_size_name(pair.key.value)
    is_weak_key_size(pair.value)
}

# FunctionCall check for hash/crypto functions with weak algorithms
func_call_has_weak_crypto(fc) {
    fc.ir_type == "FunctionCall"
    regex.match("(?i)^(filter\\|)?(hash|encrypt|cipher|crypto|md5|sha1)$", fc.name)
    arg := fc.args[_]
    arg.ir_type == "String"
    is_weak_algorithm(arg.value)
}

# Main rule: Detect weak crypto in attributes with crypto-related names
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]
    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    is_crypto_config_name(attr.name)

    val := attr.value

    # Check String values directly
    val.ir_type == "String"
    is_weak_algorithm(val.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak or deprecated cryptographic algorithm detected. (CWE-326)"
    }
}

# Detect weak cipher suites in strings
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]
    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    is_crypto_config_name(attr.name)

    val := attr.value
    val.ir_type == "String"
    has_weak_cipher_pattern(val.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak cipher suite detected (CBC mode, MD5, SHA1, or other weak primitives). (CWE-326)"
    }
}

# Detect weak password crypto in encrypt fields (like md5_crypt)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]
    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    attr.name == "encrypt"

    val := attr.value
    val.ir_type == "String"
    is_weak_password_crypto(val.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak password hashing/encryption method detected. (CWE-326)"
    }
}

# Detect weak key sizes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]
    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    is_key_size_name(attr.name)
    is_weak_key_size(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Key size below recommended minimum (2048 bits for RSA/DSA/DH). (CWE-326)"
    }
}

# Detect weak crypto in hash values within attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]
    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    hash_contains_weak_crypto(attr.value)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak cryptographic configuration detected in nested structure. (CWE-326)"
    }
}

# Detect weak crypto in variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    v := vars[_]

    is_crypto_config_name(v.name)

    val := v.value

    val.ir_type == "String"
    is_weak_algorithm(val.value)

    result := {
        "type": "sec_weak_crypt",
        "element": v,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak or deprecated cryptographic algorithm in variable. (CWE-326)"
    }
}

# Detect weak cipher patterns in variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    vars := glitch_lib.all_variables(parent)
    v := vars[_]

    is_crypto_config_name(v.name)

    val := v.value
    val.ir_type == "String"
    has_weak_cipher_pattern(val.value)

    result := {
        "type": "sec_weak_crypt",
        "element": v,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak cipher suite detected in variable. (CWE-326)"
    }
}

# Detect weak crypto in conditional statement variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    conditions := glitch_lib.all_conditional_statements(parent)
    cond := conditions[_]

    stmt := cond.statements[_]
    stmt.ir_type == "Variable"

    is_crypto_config_name(stmt.name)

    val := stmt.value
    val.ir_type == "String"

    is_weak_algorithm(val.value)

    result := {
        "type": "sec_weak_crypt",
        "element": stmt,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak or deprecated cryptographic algorithm in conditional block. (CWE-326)"
    }
}

# Detect weak cipher patterns in conditional statement variables
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    conditions := glitch_lib.all_conditional_statements(parent)
    cond := conditions[_]

    stmt := cond.statements[_]
    stmt.ir_type == "Variable"

    is_crypto_config_name(stmt.name)

    val := stmt.value
    val.ir_type == "String"
    has_weak_cipher_pattern(val.value)

    result := {
        "type": "sec_weak_crypt",
        "element": stmt,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak cipher suite detected in conditional block. (CWE-326)"
    }
}

# Detect hash function calls with weak algorithms
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    [_, fc] := walk(parent)
    func_call_has_weak_crypto(fc)

    result := {
        "type": "sec_weak_crypt",
        "element": fc,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Weak cryptographic function call detected. (CWE-326)"
    }
}

# Detect weak crypto in deeply nested hash structures (for vars_prompt style)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Walk to find any Hash with encrypt key
    [_, h] := walk(parent)
    h.ir_type == "Hash"

    # Check if this hash has an encrypt field with weak value
    pair := h.value[_]
    pair.key.ir_type == "String"
    pair.key.value == "encrypt"
    pair.value.ir_type == "String"
    is_weak_password_crypto(pair.value.value)

    result := {
        "type": "sec_weak_crypt",
        "element": h,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Use of weak password encryption method detected in configuration. (CWE-326)"
    }
}

# Detect weak crypto in small salt sizes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]
    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    attr.name == "salt_size"

    val := attr.value
    val.ir_type == "Integer"
    val.value < 16

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Inadequate Encryption Strength - Salt size below recommended minimum (16 bytes). (CWE-326)"
    }
}

iterations.nl_error_summary:
 I found the issue. The `walk_values` function starting at line 91 uses `vals` as both a **parameter** and a **return variable** in each of its else-branches, which is what OPA calls "redeclared." In each `else = vals` branch, the `vals` on the right side of `=` shadows/hides the function parameter `vals`, causing the error.

**The fix:** Use a different name for the result variable in each branch. Change `= vals` to `= result` (or another distinct name) and ensure consistency. For example, rewrite `walk_values` as:

```rego
walk_values(node, vals) = result {
    node.ir_type == "String"
    result := {node.value}
} else = result {
    node.ir_type == "VariableReference"
    result := {node.value}
}
# ... etc for all branches
```

Or alternatively, remove the parameter entirely since `vals` seems intended only as output, making it `walk_values(node)` with unification in the body if needed.

